import{_ as l,o as t,c as i,a2 as e}from"./chunks/framework.Dkj3JE0_.js";const u=JSON.parse('{"title":"CFA レベル II 計画","description":"","frontmatter":{"title":"CFA レベル II 計画"},"headers":[],"relativePath":"jp/blogs/CFA/plan.md","filePath":"jp/blogs/CFA/plan.md"}'),n={name:"jp/blogs/CFA/plan.md"};function r(o,a,s,d,h,c){return t(),i("div",null,[...a[0]||(a[0]=[e(`<h1 id="cfa-レベル-ii-学習計画" tabindex="-1">CFA レベル II 学習計画 <a class="header-anchor" href="#cfa-レベル-ii-学習計画" aria-label="Permalink to &quot;CFA レベル II 学習計画&quot;">​</a></h1><blockquote><p><strong>前提：</strong> 準備期間は 24 週間、1 週あたり約 <strong>12 時間</strong>。試験が近い場合は順序を保ったまま最初の 2 フェーズを圧縮し、最後の復習・模試フェーズは削らないこと。</p></blockquote><h2 id="完了の定義" tabindex="-1">完了の定義 <a class="header-anchor" href="#完了の定義" aria-label="Permalink to &quot;完了の定義&quot;">​</a></h2><ul><li>すべてのカリキュラムのリーディングと章末問題を終える。</li><li>2 冊目の教科書ではなく、コンパクトな公式・ミスノートを 1 冊作る。</li><li><strong>時間を計った模試 3 回すべてで 70% 以上</strong>を取り、60% を繰り返し下回る科目をなくす。</li><li>主要な評価手法とその前提、よくある落とし穴を、ノートを見ずに説明できる。</li></ul><h2 id="週のリズム" tabindex="-1">週のリズム <a class="header-anchor" href="#週のリズム" aria-label="Permalink to &quot;週のリズム&quot;">​</a></h2><table tabindex="0"><thead><tr><th>セッション</th><th style="text-align:right;">時間</th><th>内容</th></tr></thead><tbody><tr><td>平日 3 回</td><td style="text-align:right;">各 90 分</td><td>概念ブロックを 1 つ学び、ノートを閉じて 15–25 問解く。</td></tr><tr><td>平日の短いセッション 1 回</td><td style="text-align:right;">45 分</td><td>公式の想起とミスノートの見直し。</td></tr><tr><td>週末の集中学習</td><td style="text-align:right;">5–6 時間</td><td>科目の仕上げ、ミックス演習、アイテムセット 1 つの振り返り。</td></tr></tbody></table><p><strong>40/60 の配分</strong>を守る：読む・視聴するのは 40% まで、少なくとも 60% は想起・計算・アイテムセット演習に充てる。</p><h2 id="_24-週間のロードマップ" tabindex="-1">24 週間のロードマップ <a class="header-anchor" href="#_24-週間のロードマップ" aria-label="Permalink to &quot;24 週間のロードマップ&quot;">​</a></h2><h3 id="フェーズ-1-—-全体把握と診断-第-1–2-週" tabindex="-1">フェーズ 1 — 全体把握と診断（第 1–2 週） <a class="header-anchor" href="#フェーズ-1-—-全体把握と診断-第-1–2-週" aria-label="Permalink to &quot;フェーズ 1 — 全体把握と診断（第 1–2 週）&quot;">​</a></h3><ul><li>CFA の受験者向け資料で、試験日と最新のカリキュラム版を確認する。</li><li>準備なしで 60–90 問の診断テストを受ける。</li><li>間違えた問題すべてにタグを付ける：<code>knowledge</code>（知識）、<code>formula</code>（公式）、<code>interpretation</code>（解釈）、<code>calculator</code>（電卓）、<code>time</code>（時間）。</li><li>ミスノートを 1 つ作る：出典、誤答が正しく見えた理由、正しいルール、復習日。</li></ul><h3 id="フェーズ-2-—-1-周目-第-3–14-週" tabindex="-1">フェーズ 2 — 1 周目（第 3–14 週） <a class="header-anchor" href="#フェーズ-2-—-1-周目-第-3–14-週" aria-label="Permalink to &quot;フェーズ 2 — 1 周目（第 3–14 週）&quot;">​</a></h3><p>理解が積み重なる順番で学ぶ：</p><ol><li>定量分析と経済学</li><li>財務諸表分析</li><li>コーポレート・イシュアー</li><li>株式評価</li><li>債券</li><li>デリバティブ</li><li>オルタナティブ投資</li><li>ポートフォリオ運用</li></ol><p>倫理は毎週短いセットを 1 つ解いて感覚を保つ。各科目の最後に時間を計ったミックス問題を解き、1 ページのまとめを書く：重要な判断、公式、失敗パターン。</p><h3 id="フェーズ-3-—-統合-第-15–19-週" tabindex="-1">フェーズ 3 — 統合（第 15–19 週） <a class="header-anchor" href="#フェーズ-3-—-統合-第-15–19-週" aria-label="Permalink to &quot;フェーズ 3 — 統合（第 15–19 週）&quot;">​</a></h3><ul><li>章ごとの学習をミックスのアイテムセットに切り替える。</li><li>毎週 45–60 分の時間制限ブロックを 2 回行う。</li><li>記録したミスはすべて 2 日後、1 週間後、3 週間後に解き直す。</li><li>関連分野を組み合わせる：財務諸表分析 ↔ 株式、経済学 ↔ ポートフォリオ運用、債券 ↔ デリバティブ。</li><li>毎週の終わりに、科目別・ミスの種類別のスコア表を作る。</li></ul><h3 id="フェーズ-4-—-本番モード-第-20–23-週" tabindex="-1">フェーズ 4 — 本番モード（第 20–23 週） <a class="header-anchor" href="#フェーズ-4-—-本番モード-第-20–23-週" aria-label="Permalink to &quot;フェーズ 4 — 本番モード（第 20–23 週）&quot;">​</a></h3><ul><li>毎週末、本番と同じ条件でフル模試を 1 回受ける。</li><li>模試の見直しには、解いた時間と同じかそれ以上をかける。</li><li>平日は弱い 2 科目の補強だけに絞り、目的のない読み返しは避ける。</li><li>週に 1 回、主要な公式シートを記憶から書き起こす。</li></ul><h3 id="フェーズ-5-—-調整-第-24-週" tabindex="-1">フェーズ 5 — 調整（第 24 週） <a class="header-anchor" href="#フェーズ-5-—-調整-第-24-週" aria-label="Permalink to &quot;フェーズ 5 — 調整（第 24 週）&quot;">​</a></h3><ul><li>短く質の高いミックス演習を行い、試験の数日前にはフル模試をやめる。</li><li>倫理、公式、繰り返すミス、電卓の手順、試験当日の段取りを確認する。</li><li>睡眠を守り、自信を保つ。新しい教材には手を出さない。</li></ul><h2 id="週次振り返りテンプレート" tabindex="-1">週次振り返りテンプレート <a class="header-anchor" href="#週次振り返りテンプレート" aria-label="Permalink to &quot;週次振り返りテンプレート&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes min-light min-dark vp-code" tabindex="0"><code><span class="line"><span>予定 / 実績の時間：</span></span>
<span class="line"><span>解いた問題数 / 正答率：</span></span>
<span class="line"><span>最も弱い科目とミスのパターン：</span></span>
<span class="line"><span>いま人に教えられる概念を 1 つ：</span></span>
<span class="line"><span>来週変えることを 1 つ：</span></span></code></pre></div><h2 id="最初の-7-日間" tabindex="-1">最初の 7 日間 <a class="header-anchor" href="#最初の-7-日間" aria-label="Permalink to &quot;最初の 7 日間&quot;">​</a></h2><ul><li>[ ] 試験日、残り週数、週ごとの時間予算を記録する。</li><li>[ ] 診断テストを受けて採点する。</li><li>[ ] ミスノートと公式カードを作る。</li><li>[ ] 最初の 2 つの科目ブロックを決める。</li><li>[ ] 週が始まる前に、すべてのセッションをカレンダーに入れる。</li></ul><h2 id="モジュールノート" tabindex="-1">モジュールノート <a class="header-anchor" href="#モジュールノート" aria-label="Permalink to &quot;モジュールノート&quot;">​</a></h2><p>この計画を読んだら、ページ下部の「次のページ」から最初のモジュールノートに進みます。すべてのノートは<a href="/jp/blogs/0-start.html#cfa-level-ii-directory">学習ベースの目次</a>にカリキュラム順で並んでいます。</p>`,26)])])}const b=l(n,[["render",r]]);export{u as __pageData,b as default};
